/**
 * The credential SDK core. Thread-safe; see the crate documentation for the
 * concurrency contract. Build **one per storage** and share it.
 */
public protocol CredentialCoreProtocol: AnyObject, Sendable {
    
    func acknowledgeAlert(alertId: String) throws 
    
    func approvals(query: ApprovalsQuery) throws  -> Approvals
    
    /**
     * The one biometric step: sign and send the pending transaction, at
     * most once.
     */
    func approve(handle: ApprovalHandle) throws  -> ApprovalOutcome
    
    /**
     * The mdoc issue's approval: the host's proof and the core's own
     * presentation in one scope.
     */
    func approveMdocIssue(handle: ApprovalHandle, hostProof: MdocProofSigner) throws  -> MdocIssued
    
    /**
     * M4: forget the token. Never traps.
     */
    func cancelMacPasskey(token: String) 
    
    /**
     * Drop a pending transaction the person declined, before any prompt. A
     * handle that is not the one held `approved` (unknown, superseded,
     * signing, sending or spent) is left alone. Never traps: a panic inside
     * leaves the transaction as it was.
     */
    func cancelPending(handle: ApprovalHandle) 
    
    /**
     * Drop every Mac passkey token. Never traps.
     */
    func clearMacPasskeyTokens() 
    
    /**
     * The host-supplied OID4VP request path (today's `createPresentation`):
     * a presentation of a stored credential for the verifier request the
     * host hands over. It never reads or touches a pending transaction:
     * the request is the host's choice. Nothing is sent.
     * A high-assurance KB-JWT is signed in a scope of its own that allows one
     * signature (`lifecycle::presentation` in the core crate).
     */
    func createPresentation(authRequestJson: String) throws  -> PresentationResult
    
    func deviceAlerts() throws  -> DeviceAlerts
    
    func devicesList() throws  -> DeviceListing
    
    func endSiteSignin(handle: String) throws  -> SiteSignInEnded
    
    /**
     * "No, remove it": device JWT, no biometric.
     */
    func endorsementCancel(transactionId: String) throws  -> EndorsementCancelled
    
    func endorsementFinish() throws  -> EnrollResult
    
    func endorsementOpen(opts: EndorsementOpenOptions) throws  -> EndorsementOpened
    
    func endorsementStatus() throws  -> EndorsementStatus
    
    func endorsementStatusRequest() throws  -> StatusRequest
    
    func enrollOauth2(accessToken: String) throws  -> EnrollResult
    
    /**
     * iOS wrapper only in v2.
     */
    func fetchRevocationSnapshot() throws  -> RevocationSnapshot
    
    /**
     * Generate both key pairs (offline, no challenge).
     */
    func generateKeyPairs() throws 
    
    func getState() throws  -> SdkState
    
    func identityGraph() throws  -> IdentityGraph
    
    func inspectEndorsementOptical(payload: Data) throws  -> PendingTransaction
    
    func inspectEndorsementQr(qrPayload: String) throws  -> PendingTransaction
    
    func inspectSiteSignin(payload: Data) throws  -> PendingTransaction
    
    func mdocIssueChallenge() throws  -> MdocIssueChallenge
    
    /**
     * The host proof's signing input the core built at prepare time, for
     * the approval sheet; `None` when `handle` is not the prepared mdoc issue.
     * Never traps: a panic inside answers `None`.
     */
    func mdocProofSigningInput(handle: ApprovalHandle)  -> String?
    
    func prepareDeviceContain(targetDeviceId: String, since: UInt64) throws  -> PendingTransaction
    
    func prepareDeviceRevoke(targetDeviceId: String) throws  -> PendingTransaction
    
    /**
     * M1: the statement and the KB-JWT signing input the extension signs,
     * under a fresh token. Refuses typed before any draft exists: not
     * enrolled, the tombstone or latch, a field the kernel would refuse (by
     * name), no high-assurance credential. No request, no storage write.
     */
    func prepareMacPasskey(tenant: String, request: MacPasskeyRequest) throws  -> MacPasskeyPrepared
    
    /**
     * No proof yet: the host proof is signed at approval.
     */
    func prepareMdocIssue(challenge: String, tenant: String, deviceKey: EcPublicJwk) throws  -> PendingTransaction
    
    func preparePasskeyRevoke(targetJti: String) throws  -> PendingTransaction
    
    func prepareRecoveryCancel(transactionId: String) throws  -> PendingTransaction
    
    /**
     * M5 after the app's own `changed` verdict: the self-revoke, only for a
     * live token of this enrollment (else `StaleReport`, nothing destroyed).
     */
    func reportHighAssuranceInvalidated(token: String) throws  -> KeyInvalidatedOutcome
    
    /**
