public struct FfiConverterTypeCredentialCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CredentialCore

    public static func lift(_ handle: UInt64) throws -> CredentialCore {
        return CredentialCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CredentialCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CredentialCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CredentialCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


