    public var identityVersionAtIssuance: Int64
    public var issuedAt: String
    public var expiresAt: String
    public var revokedAt: String?
    public var revocationSeq: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(jti: String, agentId: String, humanAuthorizationJti: String?, status: DeviceStatus, grants: GrantMap?, authorizerDeviceId: String, identityVersionAtIssuance: Int64, issuedAt: String, expiresAt: String, revokedAt: String?, revocationSeq: Int64?) {
        self.jti = jti
        self.agentId = agentId
        self.humanAuthorizationJti = humanAuthorizationJti
        self.status = status
        self.grants = grants
        self.authorizerDeviceId = authorizerDeviceId
        self.identityVersionAtIssuance = identityVersionAtIssuance
        self.issuedAt = issuedAt
        self.expiresAt = expiresAt
        self.revokedAt = revokedAt
        self.revocationSeq = revocationSeq
    }

    

    
}

