/**
 * One pending transaction: the facts the approval sheet shows
 * and the handle `approve` consumes, both read from the one immutable
 * struct the core will sign from. Nothing here is an input: the host cannot
 * hand any of it back except the handle.
 */
public struct PendingTransaction: Equatable, Hashable {
    public var handle: ApprovalHandle
    public var facts: Facts
    /**
     * The signing digest (the presentation nonce), base64url.
     */
    public var nonceDigest: String
    /**
     * The claims the presentation discloses.
     */
    public var disclosedClaims: [String]
    /**
     * Every signature the approval makes, in order.
     */
    public var signatures: [SignatureSpec]
    /**
     * Server facts shown but never signed (the endorsement row's).
     */
    public var createdAt: String?
    public var attestation: AttestationFacts?
    /**
     * Where the approval's answer is posted (the request's `response_uri`).
     */
    public var responseUri: String
    /**
     * The OID4VP authorization request the approval answers, as JSON text,
     * built from the struct alone (`client_id` the recipient, `nonce` the
     * digest). Read-only: `approve` rebuilds it from the same struct.
     */
    public var authorizationRequest: String
    /**
     * The site's nonce, a signed input of `krutho-site-signin/1`, for the
     * site sign-in kind only (today's `SiteSignInInvitation.siteNonce`); `None`
     * for every other kind.
     */
    public var siteNonce: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(handle: ApprovalHandle, facts: Facts, 
        /**
         * The signing digest (the presentation nonce), base64url.
         */nonceDigest: String, 
        /**
         * The claims the presentation discloses.
         */disclosedClaims: [String], 
        /**
         * Every signature the approval makes, in order.
         */signatures: [SignatureSpec], 
        /**
         * Server facts shown but never signed (the endorsement row's).
         */createdAt: String?, attestation: AttestationFacts?, 
        /**
         * Where the approval's answer is posted (the request's `response_uri`).
         */responseUri: String, 
        /**
         * The OID4VP authorization request the approval answers, as JSON text,
         * built from the struct alone (`client_id` the recipient, `nonce` the
         * digest). Read-only: `approve` rebuilds it from the same struct.
         */authorizationRequest: String, 
        /**
         * The site's nonce, a signed input of `krutho-site-signin/1`, for the
         * site sign-in kind only (today's `SiteSignInInvitation.siteNonce`); `None`
         * for every other kind.
         */siteNonce: String?) {
        self.handle = handle
        self.facts = facts
        self.nonceDigest = nonceDigest
        self.disclosedClaims = disclosedClaims
        self.signatures = signatures
        self.createdAt = createdAt
        self.attestation = attestation
        self.responseUri = responseUri
        self.authorizationRequest = authorizationRequest
        self.siteNonce = siteNonce
    }

    

    
}

