public enum AppIntegrity: Equatable, Hashable {
    
    case appleAppAttest
    case none





}

#if compiler(>=6)
extension AppIntegrity: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppIntegrity: FfiConverterRustBuffer {
    typealias SwiftType = AppIntegrity

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppIntegrity {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .appleAppAttest
        
        case 2: return .none
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppIntegrity, into buf: inout [UInt8]) {
        switch value {
        
        
