/**
 * What the Mac passkey exports throw: the door's typed
 * refusals, core-api's phase A refusal, and the core's other failures
 * flattened to the cases a host acts on. A separate type from [`SdkError`]
 * so the hosts' exhaustive matches on that one keep their shape.
 */
public 
enum MacPasskeyError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The core refused; nothing was sent and nothing destroyed.
     * `field_name` names the refused field for `InvalidInput`.
     */
    case Refused(refusal: MacPasskeyRefusal, fieldName: String?, text: String
    )
    /**
     * core-api refused phase A: its reason and detail.
     */
    case ServerRefused(status: UInt16, reason: String, detail: String?, text: String
    )
    /**
     * The request did not complete.
     */
    case NetworkUnreachable(operation: String, text: String
    )
    /**
     * A storage failure.
     */
    case StorageError(code: String, detail: String, text: String
    )
    /**
     * A key-layer failure (the device JWT's standard-assurance signature).
     */
    case KeyError(code: String, detail: String, text: String
    )
    /**
     * Anything else: the text is the whole story.
     */
    case Protocol(text: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension MacPasskeyError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMacPasskeyError: FfiConverterRustBuffer {
    typealias SwiftType = MacPasskeyError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MacPasskeyError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Refused(
            refusal: try FfiConverterTypeMacPasskeyRefusal.read(from: &buf), 
            fieldName: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ServerRefused(
            status: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NetworkUnreachable(
            operation: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 4: return .StorageError(
            code: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 5: return .KeyError(
            code: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Protocol(
            text: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MacPasskeyError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Refused(refusal,fieldName,text):
            writeInt(&buf, Int32(1))
            FfiConverterTypeMacPasskeyRefusal.write(refusal, into: &buf)
            FfiConverterOptionString.write(fieldName, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .ServerRefused(status,reason,detail,text):
            writeInt(&buf, Int32(2))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .NetworkUnreachable(operation,text):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(operation, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .StorageError(code,detail,text):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .KeyError(code,detail,text):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .Protocol(text):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(text, into: &buf)
            
        }
    }
}


