/**
 * What an adapter throws (the core's `adapters::PlatformError`).
 */
public 
enum PlatformError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A key-layer failure; `code` is the stable code (`KeychainKeysError.bridgeCode`).
     */
