    )
    /**
     * An iOS storage failure; `code` is `KeychainStorageError.bridgeCode`.
     */
    case Storage(code: String, detail: String
    )
    /**
     * The request did not complete (no connection, timeout, refused redirect).
     */
    case Transport(detail: String
    )
    /**
     * The adapter does not implement this call (Android `fetch_binary`).
     */
    case Unsupported(detail: String
    )
    /**
     * Anything else; the text is the whole story.
     */
    case Other(detail: String
    )

    

    

    
