/**
 * Every failure a core call reports.
 */
public 
enum SdkError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A key-layer failure (`key_error:<code>: <detail>`), including the
     * Android storage failures that arrive as code `storage_failed`.
     */
    case KeyError(code: String, detail: String, text: String
    )
    /**
     * An iOS storage failure (`storage_error:<code>: <detail>`).
     */
    case StorageError(code: String, detail: String, text: String
    )
    /**
     * The request did not complete; `operation` names the call.
     */
    case NetworkUnreachable(operation: String, text: String
    )
    /**
     * The device already holds an enrollment.
     */
    case AlreadyEnrolled(text: String
    )
    /**
     * `409 device_exists`: this identity already has a device.
     */
    case DeviceExists(reason: String?, text: String
    )
    /**
     * Attestation failed before the enroll request was sent; `detail` is
     * the underlying failure (the core's `cause`).
     */
    case AttestationFailed(stage: AttestationStage, detail: String?, text: String
    )
    /**
     * The enroll request was refused by attestation policy.
     */
    case AttestationRefused(status: UInt16, code: String, reason: String?, text: String
    )
    /**
     * A door's route refused with a 4xx code.
     */
    case EndorsementRefused(status: UInt16, code: String, reason: String?, text: String
    )
    /**
     * The mdoc issuance route is absent on this server (404
     * `mdoc_route_absent`).
     */
    case MdocRouteAbsent(text: String
    )
    /**
     * The high-assurance key was invalidated by a biometric change; the core
     * self-revoked as far as it could.
     */
    case KeyInvalidated(revoked: Bool, cleanup: Cleanup, retryable: Bool, text: String
    )
    /**
     * `unenroll` reached the server but local cleanup did not finish;
     * `detail` is the cleanup step's failure (the core's `cause`).
     */
    case UnenrollCleanupFailed(retryable: Bool, detail: String, text: String
    )
    /**
     * `reset_local_state` wrote the tombstone but cleanup did not finish;
     * `detail` is the cleanup step's failure (the core's `cause`).
     */
    case ResetCleanupFailed(retryable: Bool, detail: String, text: String
    )
    /**
     * A revocation-snapshot fetch was refused.
     */
    case RevocationSnapshot(kind: RevocationSnapshotFailure, detail: String, text: String
    )
    /**
     * The pending-transaction model refused.
     */
    case Transaction(kind: TransactionRefusal, text: String
    )
    /**
     * `enroll_oauth2` found a pending enrollment attempt it cannot replay and
     * must not discard. `code` is the stable token
     * that follows `enrollment_attempt_conflict:` in `text`.
     */
    case EnrollmentAttemptConflict(reason: AttemptConflict, code: String, text: String
    )
    /**
     * The call exists on the surface but this build of the core does not
     * perform it. No export of this build answers it
     * (`create_presentation` was the last one that did); the variant stays so a
     * host's exhaustive match does not change shape.
     */
    case Unsupported(operation: String, text: String
    )
    /**
     * Any other refusal: the text is the whole story (a malformed reply, a
     * refused input, a missing stored value).
     */
    case Protocol(text: String
    )
    /**
     * The core panicked and the boundary caught it (a bug). Only the calls
     * that cannot otherwise report one return it (the constructor); a panic
     * in any other throwing call reaches the host as UniFFI's own
     * internal error.
     */
    case Internal(text: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

