            text: try FfiConverterString.read(from: &buf)
            )
        case 4: return .AlreadyEnrolled(
            text: try FfiConverterString.read(from: &buf)
            )
        case 5: return .DeviceExists(
            reason: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 6: return .AttestationFailed(
            stage: try FfiConverterTypeAttestationStage.read(from: &buf), 
            detail: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 7: return .AttestationRefused(
