            code: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 8: return .EndorsementRefused(
            status: try FfiConverterUInt16.read(from: &buf), 
            code: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterOptionString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 9: return .MdocRouteAbsent(
            text: try FfiConverterString.read(from: &buf)
            )
        case 10: return .KeyInvalidated(
            revoked: try FfiConverterBool.read(from: &buf), 
            cleanup: try FfiConverterTypeCleanup.read(from: &buf), 
            retryable: try FfiConverterBool.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 11: return .UnenrollCleanupFailed(
            retryable: try FfiConverterBool.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 12: return .ResetCleanupFailed(
            retryable: try FfiConverterBool.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 13: return .RevocationSnapshot(
            kind: try FfiConverterTypeRevocationSnapshotFailure.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 14: return .Transaction(
            kind: try FfiConverterTypeTransactionRefusal.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 15: return .EnrollmentAttemptConflict(
            reason: try FfiConverterTypeAttemptConflict.read(from: &buf), 
            code: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 16: return .Unsupported(
            operation: try FfiConverterString.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 17: return .Protocol(
            text: try FfiConverterString.read(from: &buf)
            )
        case 18: return .Internal(
            text: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SdkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .KeyError(code,detail,text):
