            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .StorageError(code,detail,text):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .NetworkUnreachable(operation,text):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(operation, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .AlreadyEnrolled(text):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .DeviceExists(reason,text):
            writeInt(&buf, Int32(5))
            FfiConverterOptionString.write(reason, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .AttestationFailed(stage,detail,text):
            writeInt(&buf, Int32(6))
            FfiConverterTypeAttestationStage.write(stage, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .AttestationRefused(status,code,reason,text):
